import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"給初學者的 type 命令教程 | LCTT x X-CMD","titleTemplate":false,"description":"給初學者的 type 命令教程 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"給初學者的 type 命令教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"給初學者的 type 命令教程 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180313 The Type Command Tutorial With Examples For Beginners","title":"給初學者的 type 命令教程","tag":"201804","desc":""},"relativePath":"201804/20180313 The Type Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),c={name:"201804/20180313 The Type Command Tutorial With Examples For Beginners.md"};function h(g,s,u,m,k,y){const e=l("Link");return o(),d("div",null,[s[13]||(s[13]=r(`<h1 id="給初學者的-type-命令教程" tabindex="-1">給初學者的 type 命令教程 <a class="header-anchor" href="#給初學者的-type-命令教程" aria-label="Permalink to “給初學者的 type 命令教程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Type-command-720x340.png" alt=""></p><p><code>type</code> 命令用於查找 Linux 命令的信息。顧名思義，你可以使用 <code>type</code> 命令輕鬆找出給定的命令是否是別名、shell 內置命令、文件、函數或關鍵字。另外，你也可以找到命令的實際路徑。為什麼有人需要找到命令類型？例如，如果你經常在共享的計算機上工作，則某些人可能會故意或意外地為特定的 Linux 命令創建別名來執行不需要的操作，例如 <code>alias ls = rm -rf /</code>。因此，在發生更糟糕的事情之前檢查它們總是一個好主意。這是 <code>type</code> 命令有用的地方。</p><p>讓我給你看一些例子。</p><p>不帶任何選項運行 <code>type</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type ls</span></span>
<span class="line"><span>ls is aliased to \`ls --color=auto&#39;</span></span></code></pre></div><p>正如你在上面的輸出中看到的那樣，<code>ls</code> 命令已被別名為 <code>ls -color-auto</code>。但是，它是無害的。但只要想想 <code>ls</code> 如果被別名為了其他一些危險的命令。你不想那樣，是嗎？</p><p>你可以使用 <code>-t</code> 選項僅找出 Linux 命令的類型。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -t ls</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t mkdir</span></span>
<span class="line"><span>file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t pwd</span></span>
<span class="line"><span>builtin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t if</span></span>
<span class="line"><span>keyword</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t rvm</span></span>
<span class="line"><span>function</span></span></code></pre></div><p>該命令僅顯示命令的類型，例如別名。它不顯示被別名的內容。如果該命令找不到，你將在終端中看不到任何內容。</p><p><code>type</code> 命令的另一個有用的地方是我們可以很容易地找出給定 Linux 命令的絕對路徑。為此，請使用 <code>-p</code> 選項，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -p cal</span></span>
<span class="line"><span>/usr/bin/cal</span></span></code></pre></div><p>這與 <code>which ls</code> 命令類似。如果給定的命令是別名，則不會打印任何內容。</p><p>要顯示命令的所有信息，請使用 <code>-a</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -a ls</span></span>
<span class="line"><span>ls is aliased to \`ls --color=auto&#39;</span></span>
<span class="line"><span>ls is /usr/bin/ls</span></span>
<span class="line"><span>ls is /bin/ls</span></span></code></pre></div><p>如你所見，<code>-a</code> 標誌顯示給定命令的類型及其絕對路徑。有關更多詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man type</span></span></code></pre></div><p>希望這有幫助。會有更多的好東西。請繼續訪問！</p><p>乾杯!</p><hr>`,20)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.ostechnix.com/the-type-command-tutorial-with-examples-for-beginners/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/the-type-command-tutorial-with-examples-for-beginners/",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[3]||(s[3]=[a("geekpi",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const x=i(c,[["render",h]]);export{T as __pageData,x as default};
